                    java.util.Arrays.toString(ArrayRotator.rotateRight(new int[]{7, 8}, 0)));
            check("rotateRight({1,2,3}, 3) full cycle", "[1, 2, 3]",
                    java.util.Arrays.toString(ArrayRotator.rotateRight(new int[]{1, 2, 3}, 3)));
